mapper.select:
SELECT go.source_type, CASE WHEN go.source_type = 'initiated' THEN go.initiated_id ELSE go.group_activity_id END AS source_id, gw.id AS group_work_id, go.group_activity_id AS activity_id, ga.title, ga.cpu, ga.memory, ga.storage, COALESCE(go.base_price, ga.base_price) AS base_price, gw.actual_price, COALESCE(gui.duration, ga.total_duration) AS total_duration, COALESCE(gui.initiate_time, ga.start_time) AS start_time, gw.server_start_time, gw.server_expire_time, gw.group_status, CASE gw.group_status WHEN 0 THEN '进行中' WHEN 1 THEN '已成团' WHEN 2 THEN '已取消/过期' ELSE '未知' END AS group_status_text, go.order_no, go.status AS order_status, gw.join_time, NULL AS admin_contact FROM osh_group_work gw JOIN osh_group_order go ON gw.order_id = go.id AND gw.user_id = go.user_id LEFT JOIN osh_group_user_initiated gui ON go.source_type = 'initiated' AND gui.id = go.initiated_id LEFT JOIN osh_group_activity ga ON ga.id = go.group_activity_id WHERE gw.user_id = #{userId} AND go.source_type IN ('system', 'initiated') AND go.delete_flag = 0
AND gw.group_status = #{groupStatus}
ORDER BY gw.join_time DESC

SELECT 'initiated' AS source_type, gui.id AS group_work_id, gui.activity_id AS activity_id, COALESCE(ga.title, '未知活动') AS title, COALESCE(ga.cpu, '待定') AS cpu, COALESCE(ga.memory, '待定') AS memory, COALESCE(ga.storage, '待定') AS storage, ga.base_price, gui.custom_price AS actual_price, gui.duration AS total_duration, gui.initiate_time AS start_time, gui.server_start_time, gui.server_expire_time, gui.group_status, CASE gui.group_status WHEN 0 THEN '招募中' WHEN 1 THEN '已成团' WHEN 2 THEN '已取消/过期' ELSE '未知' END AS group_status_text, go.order_no, go.status AS order_status, gui.initiate_time AS join_time, ga.admin_contact FROM osh_group_user_initiated gui LEFT JOIN osh_group_activity ga ON gui.activity_id = ga.id LEFT JOIN osh_group_order go ON gui.order_id = go.id WHERE gui.user_id = #{userId} AND gui.delete_flag = 0
AND gui.group_status = #{groupStatus}
ORDER BY gui.initiate_time DESC

