mapper.select:
SELECT 'joined' AS source_type, gw.id AS group_work_id, ga.id AS activity_id, ga.title AS activity_title, gw.user_id, u.username, u.username AS nickname, gw.actual_price, gw.remaining_months, gw.group_status, CASE gw.group_status WHEN 0 THEN '进行中' WHEN 1 THEN '已成团' WHEN 2 THEN '已取消/过期' ELSE '未知' END AS group_status_text, gw.join_time, gw.server_start_time, gw.server_expire_time, go.order_no, go.status AS order_status FROM osh_group_work gw LEFT JOIN osh_group_activity ga ON gw.group_activity_id = ga.id LEFT JOIN osh_user u ON gw.user_id = u.id LEFT JOIN osh_group_order go ON gw.order_id = go.id
gw.group_status = #{groupStatus}
UNION ALL SELECT 'initiated' AS source_type, gui.id AS group_work_id, NULL AS activity_id, '用户发起拼团' AS activity_title, gui.user_id, u.username, u.username AS nickname, gui.custom_price AS actual_price, NULL AS remaining_months, gui.group_status, CASE gui.group_status WHEN 0 THEN '招募中' WHEN 1 THEN '已成团' WHEN 2 THEN '已取消/过期' ELSE '未知' END AS group_status_text, gui.initiate_time AS join_time, gui.server_start_time, gui.server_expire_time, go.order_no, go.status AS order_status FROM osh_group_user_initiated gui LEFT JOIN osh_user u ON gui.user_id = u.id LEFT JOIN osh_group_order go ON gui.order_id = go.id
gui.delete_flag = 0
AND gui.group_status = #{groupStatus}
ORDER BY join_time DESC

SELECT gw.id AS group_work_id, ga.id AS activity_id, ga.title AS activity_title, gw.user_id, u.username, u.username AS nickname, gw.actual_price, gw.remaining_months, gw.group_status, CASE gw.group_status WHEN 0 THEN '进行中' WHEN 1 THEN '已成团' WHEN 2 THEN '已取消/过期' ELSE '未知' END AS group_status_text, gw.join_time, gw.server_start_time, gw.server_expire_time, go.order_no, go.status AS order_status FROM osh_group_work gw LEFT JOIN osh_group_activity ga ON gw.group_activity_id = ga.id LEFT JOIN osh_user u ON gw.user_id = u.id LEFT JOIN osh_group_order go ON gw.order_id = go.id
gw.group_status = #{groupStatus}
ORDER BY gw.join_time DESC

